#include <cstddef>
#include <utility>

class Buffer
{
public:
    explicit Buffer(std::size_t size) : m_data{ new int[size]{} }, m_size{ size } {}
    ~Buffer() { delete[] m_data; }
    Buffer(const Buffer& other) : m_data{ new int[other.m_size] }, m_size{ other.m_size }
    {
        for (std::size_t i{ 0 }; i < m_size; ++i) m_data[i] = other.m_data[i];
    }
    Buffer& operator=(const Buffer& other)
    {
        if (this != &other) { Buffer copy{ other }; std::swap(m_data, copy.m_data); std::swap(m_size, copy.m_size); }
        return *this;
    }

    Buffer(Buffer&& other) noexcept
        : m_data{ std::exchange(other.m_data, nullptr) }, m_size{ std::exchange(other.m_size, 0) }
    {
    }

    Buffer& operator=(Buffer&& other) noexcept
    {
        if (this != &other)
        {
            delete[] m_data;
            m_data = std::exchange(other.m_data, nullptr);
            m_size = std::exchange(other.m_size, 0);
        }
        return *this;
    }

    std::size_t size() const { return m_size; }
    const int* data() const { return m_data; }

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
};

unitTests:
static_assert(std::is_nothrow_move_constructible_v<Buffer>, "the move constructor should be noexcept");
static_assert(std::is_nothrow_move_assignable_v<Buffer>, "move assignment should be noexcept");

TEST("move construction steals the array") { Buffer a{ 100 }; const int* original{ a.data() }; Buffer b{ std::move(a) }; CHECK(b.data() == original); CHECK_EQ(b.size(), 100u); CHECK(a.data() == nullptr); CHECK_EQ(a.size(), 0u); }
TEST("move assignment steals the array") { Buffer a{ 50 }; const int* original{ a.data() }; Buffer b{ 3 }; b = std::move(a); CHECK(b.data() == original); CHECK_EQ(b.size(), 50u); CHECK(a.data() == nullptr); }
TEST("copying still copies") { Buffer a{ 5 }; Buffer b{ a }; CHECK(a.data() != b.data()); CHECK_EQ(a.size(), 5u); }
TEST("no leaks") { CHECK_NO_LEAK(Buffer a{ 10 }; Buffer b{ std::move(a) }; Buffer c{ 20 }; c = std::move(b); Buffer d{ 5 }; d = Buffer{ 30 }); }

